"""Marketing analytics and business intelligence workspace."""
from fastapi import APIRouter, Response
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["CRM analytics workspace"], include_in_schema=False)

_HEADERS = {
    "Cache-Control": "no-store",
    "Content-Security-Policy": "default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'",
    "Referrer-Policy": "no-referrer",
    "X-Content-Type-Options": "nosniff",
}
_PAGE = """<!doctype html>
<html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>تحلیل و هوش تجاری | فانل CRM</title>
<style>
:root{font-family:Tahoma,Arial,sans-serif;color:#172c42;background:#f4f7fb;font-synthesis:none}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px minmax(0,1fr)}aside{background:#fff;border-left:1px solid #e3e9f0;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:800;padding:0 10px 24px}.brand b{color:#158b91}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#54677a;text-decoration:none;font-size:12px}.nav:hover,.nav.active{background:#eaf4f7;color:#125779}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}.top{display:flex;align-items:center;gap:10px;margin-bottom:24px}.field{display:grid;gap:6px;font-size:11px;color:#778697}select,input{font:inherit;color:#33465c;border:1px solid #dfe6ed;background:#fff;border-radius:9px;padding:10px;min-width:140px}.head{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;margin-bottom:18px}h1{font-size:25px;margin:0 0 8px}.sub{color:#718092;font-size:13px;line-height:1.8;margin:0}.filters{display:flex;gap:8px;align-items:end;flex-wrap:wrap}button{font:inherit;cursor:pointer}.primary{border:0;background:#126b91;color:white;border-radius:9px;padding:11px 16px;font-weight:700}.status{min-height:21px;color:#718092;font-size:12px;margin:0 0 8px}.status.error{color:#a74137}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:14px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;box-shadow:0 4px 14px #1c334408;min-width:0}.label{color:#657487;font-size:12px}.value{font-size:22px;font-weight:800;color:#1a334c;margin:11px 0 5px;overflow-wrap:anywhere}.meta{font-size:10px;color:#8290a0;line-height:1.7}.section-grid{display:grid;grid-template-columns:1.25fr 1fr;gap:14px;margin-bottom:14px}.section-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 13px;font-size:15px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:520px;font-size:11px}th,td{text-align:right;padding:10px 8px;border-bottom:1px solid #eef1f4}th{background:#f8fafc;color:#728092;font-weight:600}td{color:#33465c}.bars{display:grid;gap:11px}.bar-row{display:grid;grid-template-columns:90px minmax(0,1fr) 70px;align-items:center;gap:9px;font-size:11px}.track{height:9px;border-radius:99px;background:#edf2f6;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#24b5a5,#17658e);border-radius:99px}.bar-number{text-align:left;color:#526477}.list{display:grid;gap:8px}.row{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #eef1f4;padding:9px 0;font-size:11px}.row strong{color:#334b60}.empty{border:1px dashed #d4dde6;border-radius:9px;padding:16px;color:#7b8998;font-size:12px;text-align:center;line-height:1.8}.note{margin-top:12px;color:#85919e;font-size:10px;line-height:1.8}.error-box{border:1px solid #f0d7d4;background:#fff7f6;border-radius:9px;padding:12px;color:#984e45;font-size:11px;line-height:1.8}
@media(max-width:1000px){.section-grid{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e3e9f0;padding:12px}.brand{padding-bottom:9px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.head{display:block}.filters{margin-top:14px}}@media(max-width:480px){.main{padding:15px 12px 32px}.top{align-items:stretch;flex-direction:column}.top select{width:100%}.filters{display:grid;grid-template-columns:1fr 1fr}.filters select,.filters input{min-width:0;width:100%}.kpis{gap:8px}.card{padding:12px}.value{font-size:18px}.bar-row{grid-template-columns:70px minmax(0,1fr) 58px}}
</style><script src="/assets/crm-analytics-workspace.js" defer></script></head>
<body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM">
<a class="nav" href="/workspace/marketing-manager">میزکار مدیر بازاریابی</a><a class="nav" href="/workspace/crm-customers">مشتریان</a><a class="nav" href="/workspace/crm-campaigns">کمپین و محتوا</a><a class="nav" href="/workspace/crm-sales">فروش و درآمد</a><a class="nav" href="/workspace/crm-operations">عملیات و منابع</a><a class="nav active" href="/workspace/crm-analytics" aria-current="page">تحلیل و هوش تجاری</a></nav></aside>
<main class="main"><div class="top"><label class="field">فضای کاری<select id="workspace-id"><option value="">در حال دریافت…</option></select></label><label class="field">واحد سازمانی<select id="organization-unit"><option value="">ابتدا فضای کاری را انتخاب کنید</option></select></label></div>
<header class="head"><div><h1>تحلیل و هوش تجاری</h1><p class="sub">عملکرد کمپین‌ها، تعامل مشتری و وضعیت چرخهٔ عمر را در یک بازهٔ زمانی بررسی کنید.</p></div><div class="filters"><label class="field">از تاریخ<input id="period-start" type="date"></label><label class="field">تا تاریخ<input id="period-end" type="date"></label><button id="refresh" class="primary" type="button">اجرای تحلیل</button></div></header>
<p id="status" class="status" role="status" aria-live="polite"></p>
<section aria-label="شاخص‌های کمپین" class="kpis"><article class="card"><div class="label">کمپین‌های ثبت‌شده</div><div id="kpi-campaigns" class="value">—</div><div class="meta">در واحد و بازهٔ انتخاب‌شده</div></article><article class="card"><div class="label">کلیک</div><div id="kpi-clicks" class="value">—</div><div class="meta">مجموع اندازه‌گیری‌های موجود</div></article><article class="card"><div class="label">سرنخ</div><div id="kpi-leads" class="value">—</div><div class="meta">بر اساس داده‌های ثبت‌شده</div></article><article class="card"><div class="label">تبدیل</div><div id="kpi-conversions" class="value">—</div><div id="kpi-conversion-rate" class="meta">نرخ تبدیل به کلیک: —</div></article></section>
<div class="section-grid"><section class="card"><h2 class="section-title">عملکرد کمپین‌ها <span id="campaign-period" class="meta"></span></h2><div id="campaign-table" class="table-wrap"><div class="empty">برای مشاهدهٔ گزارش، فضا و واحد سازمانی را انتخاب کنید.</div></div><p id="campaign-note" class="note"></p></section>
<section class="card"><h2 class="section-title">مقایسهٔ کانال‌ها</h2><div id="channel-bars" class="bars"><div class="empty">داده‌ای بارگذاری نشده است.</div></div><p class="note">مقایسه بر اساس شاخص کلیک ثبت‌شده در کمپین‌هاست؛ مقدار ناموجود به‌صورت صفر در نمودار شمرده نمی‌شود.</p></section></div>
<div class="section-grid"><section class="card"><h2 class="section-title">تعامل مشتری <span class="meta">۳۰ روز جاری در برابر ۳۰ روز قبل</span></h2><div id="activity-summary" class="kpis"><div class="empty">داده‌ای بارگذاری نشده است.</div></div><h3 class="section-title">ترکیب کانال فعالیت</h3><div id="activity-channels" class="list"></div></section>
<section class="card"><h2 class="section-title">چرخهٔ عمر مشتری <span id="lifecycle-period" class="meta"></span></h2><div id="lifecycle-stages" class="list"><div class="empty">داده‌ای بارگذاری نشده است.</div></div><p id="lifecycle-note" class="note"></p></section></div>
<p class="note">این داشبورد فقط تجمیع‌های ارائه‌شده توسط APIهای CRM را نمایش می‌دهد. انتساب علّی یا تبدیل ارز خارج از محاسباتی است که هر گزارش صریحاً اعلام می‌کند.</p></main></div></body></html>"""
_SCRIPT = """(() => {
const $=id=>document.getElementById(id),workspace=$("workspace-id"),unit=$("organization-unit"),num=new Intl.NumberFormat("fa-IR");
function say(s,error=false){$("status").textContent=s;$("status").classList.toggle("error",error)}
function el(tag,text,cls=""){const n=document.createElement(tag);n.textContent=String(text??"");if(cls)n.className=cls;return n}
async function api(path){const headers={Accept:"application/json"};if(workspace.value)headers["X-Workspace-ID"]=workspace.value;const res=await fetch(path,{credentials:"same-origin",headers});let data={};try{data=await res.json()}catch(_){}if(!res.ok){const d=typeof data.detail==="string"?data.detail:data.detail?.message;throw Error(d||"گزارش در دسترس نیست ("+res.status+").")}return data}
function localDate(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function initDates(){const end=new Date(),start=new Date();start.setDate(start.getDate()-29);$("period-start").value=localDate(start);$("period-end").value=localDate(end)}
function range(){const start=$("period-start").value,end=$("period-end").value;if(!start||!end||start>end)throw Error("بازهٔ تاریخ را بررسی کنید.");const q=new URLSearchParams({period_start:start,period_end:end});if(unit.value)q.set("organization_unit_id",unit.value);return {start,end,q}}
function showError(host,error){host.replaceChildren(el("div",error.message,"error-box"))}
function setKpi(id,value){$(id).textContent=value===null||value===undefined?"—":num.format(Number(value))}
async function loadCampaigns(ctx){const data=await api("/api/v1/crm/analytics/campaign-performance/portfolio?"+new URLSearchParams({period_start:ctx.start,period_end:ctx.end,organization_unit_id:unit.value,grouped_by:"channel",sort_by:"conversions",limit:"100"}).toString());const t=data.totals||{};setKpi("kpi-campaigns",t.campaign_count);setKpi("kpi-clicks",t.totals?.clicks);setKpi("kpi-leads",t.totals?.leads);setKpi("kpi-conversions",t.totals?.conversions);$("kpi-conversion-rate").textContent="نرخ تبدیل به کلیک: "+(t.conversion_rate_per_click_percent===null?"دادهٔ کافی نیست":num.format(t.conversion_rate_per_click_percent)+"٪");$("campaign-period").textContent=ctx.start+" تا "+ctx.end;const host=$("campaign-table");host.replaceChildren();if(!data.campaigns?.length){host.appendChild(el("div","برای این بازه دادهٔ کمپینی ثبت نشده است.","empty"))}else{const table=document.createElement("table"),thead=document.createElement("thead"),tr=document.createElement("tr");["کمپین","کانال","کلیک","سرنخ","تبدیل"].forEach(v=>tr.appendChild(el("th",v)));thead.appendChild(tr);table.appendChild(thead);const body=document.createElement("tbody");data.campaigns.forEach(c=>{const r=document.createElement("tr");[c.name,c.channel,c.totals?.clicks,c.totals?.leads,c.totals?.conversions].forEach(v=>r.appendChild(el("td",v===null||v===undefined?"—":typeof v==="number"?num.format(v):v)));body.appendChild(r)});table.appendChild(body);host.appendChild(table)}$("campaign-note").textContent=data.campaign_list_truncated?"فهرست کمپین‌ها محدود شده؛ شاخص‌های کل از تمام نتایج مجاز گزارش می‌آیند.":"تعداد کمپین: "+num.format(data.totals?.campaign_count||0)+" · رکورد اندازه‌گیری: "+num.format(data.totals?.measurement_record_count||0);const chart=$("channel-bars");chart.replaceChildren();const groups=(data.groups||[]).map(g=>({name:g.key,value:g.metrics?.totals?.clicks})).filter(x=>x.value!==null&&x.value!==undefined);if(!groups.length){chart.appendChild(el("div","دادهٔ کلیک به تفکیک کانال ثبت نشده است.","empty"));return}const max=Math.max(1,...groups.map(x=>Number(x.value)));groups.forEach(g=>{const row=document.createElement("div");row.className="bar-row";row.appendChild(el("span",g.name));const track=document.createElement("div");track.className="track";const fill=document.createElement("div");fill.className="fill";fill.style.width=Math.max(2,100*Number(g.value)/max)+"%";track.appendChild(fill);row.appendChild(track);row.appendChild(el("span",num.format(g.value),"bar-number"));chart.appendChild(row)})}
async function loadActivity(ctx){const data=await api("/api/v1/crm/analytics/customer-activities/summary?window_days=30&organization_unit_id="+encodeURIComponent(unit.value));const host=$("activity-summary");host.replaceChildren();[["فعالیت ۳۰ روز اخیر",data.current_activity_count],["۳۰ روز پیش",data.previous_activity_count],["مشتریان فعال",data.current_profiles_with_activity],["تغییر فعالیت",data.activity_count_change_percent===null?"—":num.format(data.activity_count_change_percent)+"٪"]].forEach(([label,value])=>{const card=document.createElement("article");card.className="card";card.appendChild(el("div",label,"label"));card.appendChild(el("div",typeof value==="number"?num.format(value):value,"value"));host.appendChild(card)});const list=$("activity-channels");list.replaceChildren();if(!data.by_channel?.length){list.appendChild(el("div","فعالیتی در این بازه ثبت نشده است.","empty"));return}data.by_channel.forEach(item=>{const row=document.createElement("div");row.className="row";row.appendChild(el("strong",item.key));row.appendChild(el("span",num.format(item.current_count)+" · پیشین "+num.format(item.previous_count)));list.appendChild(row)})}
async function loadLifecycle(ctx){const data=await api("/api/v1/crm/analytics/customer-lifecycle?"+new URLSearchParams({period_start:ctx.start,period_end:ctx.end,organization_unit_id:unit.value,limit:"100"}).toString());$("lifecycle-period").textContent=ctx.start+" تا "+ctx.end;const host=$("lifecycle-stages");host.replaceChildren();if(!data.cohorts?.length){host.appendChild(el("div","گروهی برای نمایش در این بازه پیدا نشد.","empty"))}else data.cohorts.forEach(c=>{const row=document.createElement("div");row.className="row";row.appendChild(el("strong",c.profile_kind+" · "+c.current_lifecycle_stage));row.appendChild(el("span",num.format(c.current_profile_count)+" مشتری"));host.appendChild(row)});$("lifecycle-note").textContent="مشتریان در "+num.format(data.total_cohort_count)+" گروه نوع و مرحله دسته‌بندی شده‌اند. "+(data.has_more?"برای دیدن همهٔ گروه‌ها به صفحه‌بندی نیاز است.":"")+" "+(data.causal_attribution_applied?"انتساب علّی اعمال شده است.":"انتساب علّی اعمال نشده است.")}
async function load(){if(!workspace.value||!unit.value){say("فضای کاری و واحد سازمانی را انتخاب کنید.");return}let ctx;try{ctx=range()}catch(e){say(e.message,true);return}say("در حال دریافت شاخص‌ها…");const results=await Promise.allSettled([loadCampaigns(ctx),loadActivity(ctx),loadLifecycle(ctx)]);const hosts=["campaign-table","activity-summary","lifecycle-stages"];let failed=0;results.forEach((r,i)=>{if(r.status==="rejected"){failed++;showError($(hosts[i]),r.reason)}});say(failed?failed+" بخش به‌دلیل محدودیت دسترسی یا خطای داده بارگذاری نشد؛ سایر بخش‌ها به‌روز هستند.":"گزارش‌های تحلیلی به‌روز شدند.",failed===3)}
async function loadUnits(){unit.replaceChildren();const p=el("option","واحد سازمانی را انتخاب کنید");p.value="";unit.appendChild(p);const rows=await api("/api/v1/system/opportunity-organization-units");rows.forEach(x=>{const o=el("option",x.name);o.value=x.id;unit.appendChild(o)});if(rows.length===1)unit.value=rows[0].id;if(unit.value)await load();else say("واحد سازمانی را انتخاب کنید.")}
async function init(){initDates();try{const spaces=await api("/api/v1/system/workspaces");workspace.replaceChildren();const p=el("option","فضای کاری را انتخاب کنید");p.value="";workspace.appendChild(p);spaces.forEach(x=>{const o=el("option",x.name);o.value=x.id;workspace.appendChild(o)});const requested=new URLSearchParams(location.search).get("workspace_id");workspace.value=spaces.some(x=>x.id===requested)?requested:(spaces.length===1?spaces[0].id:"");if(workspace.value)await loadUnits();else say("فضای کاری را انتخاب کنید.")}catch(e){say(e.message,true)}}
workspace.addEventListener("change",async()=>{unit.value="";try{await loadUnits()}catch(e){say(e.message,true)}});unit.addEventListener("change",load);$("refresh").addEventListener("click",load);init();
})();"""

@router.get("/workspace/crm-analytics", response_class=HTMLResponse)
async def crm_analytics_workspace_page() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-analytics-workspace.js")
async def crm_analytics_workspace_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers={"Cache-Control":"no-store","X-Content-Type-Options":"nosniff"})
